if doc.log_type == "OUT" and doc.shift:

    attendance_date = frappe.utils.getdate(doc.time)

    if not frappe.db.exists(
        "Attendance",
        {
            "employee": doc.employee,
            "attendance_date": attendance_date
        }
    ):

        in_time = frappe.db.get_value(
            "Employee Checkin",
            {
                "employee": doc.employee,
                "log_type": "IN",
                "time": ["between", [attendance_date, f"{attendance_date} 23:59:59"]]
            },
            "time",
            order_by="time asc"
        )

        out_time = doc.time

        working_hours = 0
        overtime_hours = 0

        if in_time and out_time:

            working_hours = frappe.utils.time_diff_in_hours(out_time, in_time)

            shift = frappe.get_doc("Shift Type", doc.shift)

            shift_start = frappe.utils.get_datetime(
                f"{attendance_date} {shift.start_time}"
            )
            shift_end = frappe.utils.get_datetime(
                f"{attendance_date} {shift.end_time}"
            )

            if shift_end <= shift_start:
                shift_end = frappe.utils.add_days(shift_end, 1)

            shift_hours = frappe.utils.time_diff_in_hours(
                shift_end, shift_start
            )

            if working_hours > shift_hours:
                overtime_hours = working_hours - shift_hours

        attendance = frappe.get_doc({
            "doctype": "Attendance",
            "employee": doc.employee,
            "attendance_date": attendance_date,
            "status": "Present",
            "shift": doc.shift,
            "in_time": in_time,
            "out_time": out_time,
            "working_hours": round(working_hours, 2),
            "overtime_hours": round(overtime_hours, 2),
            "docstatus": 0  # Draft
        })

        attendance.insert(ignore_permissions=True)

        if not doc.custom_employee_chekin_location:
            attendance.add_comment(
                "Info",
                "Attendance created as Draft. Working & OT hours calculated, but check-in location is missing."
            )
